const loadLocal=(k,d)=>{try{return JSON.parse(localStorage.getItem(k))||d}catch(e){return d}};
const saveLocal=(k,v)=>localStorage.setItem(k,JSON.stringify(v));
async function loadPrepData(){
  prepItems=loadLocal("loy-prep-v011",PREP_DEFAULTS.map(x=>({...x})));
  costcoItems=loadLocal("loy-costco-v011",COSTCO_DEFAULTS.map(x=>({...x})));
  if(!sb||!trip)return;
  try{let q=await sb.from("trip_prep_items").select("*").eq("trip_id",trip.id).order("sort_order");if(!q.error&&q.data?.length){prepItems=q.data;prepUsingDb=true}}catch(e){}
  try{let q=await sb.from("costco_items").select("*").eq("trip_id",trip.id).order("sort_order");if(!q.error&&q.data?.length){costcoItems=q.data;costcoUsingDb=true}}catch(e){}
}
async function updatePrepItem(id,patch){
  let x=prepItems.find(i=>String(prepId(i))===String(id));if(!x)return;Object.assign(x,patch);
  if(prepUsingDb&&x.id){await sb.from("trip_prep_items").update(patch).eq("id",x.id)}else saveLocal("loy-prep-v011",prepItems);
  render();
}
async function updateCostcoItem(id,patch){
  let x=costcoItems.find(i=>String(costcoId(i))===String(id));if(!x)return;Object.assign(x,patch);
  if(costcoUsingDb&&x.id){await sb.from("costco_items").update(patch).eq("id",x.id)}else saveLocal("loy-costco-v011",costcoItems);
  render();
}
