async function connect(){try{ideas=await fetch("/ideas.json",{cache:"no-store"}).then(r=>r.json());try{cards=await fetch("/cards.json",{cache:"no-store"}).then(r=>r.json())}catch(e){console.warn("Card catalog:",e)}let c=await fetch("/api/config",{cache:"no-store"}).then(r=>r.json());sb=supabase.createClient(c.url,c.key);trip=(await sb.from("trips").select("*").eq("name","Maui 2026").single()).data;if(trip){travelers=(await sb.from("travelers").select("*").eq("trip_id",trip.id)).data||[];activities=(await sb.from("activities").select("*").eq("trip_id",trip.id)).data||[];votes=(await sb.from("activity_votes").select("*")).data||[];packing=(await sb.from("packing_items").select("*").eq("trip_id",trip.id)).data||[];try{food=(await sb.from("food_spots").select("*").eq("trip_id",trip.id).order("area")).data||[];foodVotes=(await sb.from("food_spot_votes").select("*")).data||[]}catch(e){console.warn("Food tables:",e)}try{advisorPicks=(await sb.from("advisor_recommendations").select("*").eq("trip_id",trip.id).eq("advisor_name","Grandpa Rick")).data||[]}catch(e){console.warn("Advisor table:",e)}await loadPrepData()}}catch(e){console.warn(e)}render()}
function head(){return `<header class="top"><div class="brand"><img src="/loy-travel-logo.png"><div><h1>Loy Travel</h1><small>Maui 2026 · Preview 0.12</small></div><button class="profile" data-switch>${isGuest()?"👀":PEOPLE[who]} ${who}${isAdvisor()?` · Advisor`:isGuest()?` · Read only`:""}</button></div></header>`}
