function splash(){return `<div class="splash"><img src="/loy-travel-logo.png"><h1>Who's traveling?</h1><p class="sub">Pick your name. This device remembers you. Grandpa Rick has advisor mode.</p><div class="profiles">${Object.entries(PEOPLE).map(([n,e])=>`<button class="pick ${n==="Grandpa Rick"?"advisor-pick":""}" data-person="${n}"><span>${e}</span>${n}${n==="Grandpa Rick"?`<small>Advisor</small>`:""}</button>`).join("")}<button class="pick guest-pick" data-guest><span>👀</span>Guest<small>Read only · code required</small></button></div></div>`}
